package android.graphics; import java.util.*; public class Path {public List<float[]> pts=new ArrayList<>();public Path(){}public Path(Path p){for(float[] v:p.pts)pts.add(v.clone());}public void moveTo(float x,float y){pts.add(new float[]{x,y});}public void lineTo(float x,float y){pts.add(new float[]{x,y});}public boolean isEmpty(){return pts.isEmpty();}public void computeBounds(RectF r,boolean exact){r.left=r.top=Float.POSITIVE_INFINITY;r.right=r.bottom=Float.NEGATIVE_INFINITY;for(float[] p:pts){r.left=Math.min(r.left,p[0]);r.right=Math.max(r.right,p[0]);r.top=Math.min(r.top,p[1]);r.bottom=Math.max(r.bottom,p[1]);}}}
